"""Maintainer-only task expectations from independent Parquet row calculations."""
from __future__ import annotations
import argparse,pathlib,datetime,decimal,collections,json,hashlib
from common import load,save
def freeze(package):
    import pyarrow.parquet as pq
    p=pathlib.Path(package);raw=p/'data/raw';tables={t:pq.read_table(raw/(t+'.parquet')).to_pylist() for t in ['Sales.Orders','Sales.OrderLines','Sales.Customers','Warehouse.StockItems','Warehouse.StockItemHoldings','Warehouse.StockItemStockGroups','Purchasing.PurchaseOrders','Purchasing.PurchaseOrderLines','Purchasing.Suppliers']}
    orders={r['OrderID']:r for r in tables['Sales.Orders']};items={r['StockItemID']:r for r in tables['Warehouse.StockItems']};customers={r['CustomerID']:r for r in tables['Sales.Customers']};pos={r['PurchaseOrderID']:r for r in tables['Purchasing.PurchaseOrders']};holds={r['StockItemID']:r for r in tables['Warehouse.StockItemHoldings']};suppliers={r['SupplierID']:r for r in tables['Purchasing.Suppliers']};fixture=load(p/'data/synthetic/no_incoming_v1/scenario.json')
    def oracle(mid,start=None,end=None,customer=None,item=None,supplier=None,group=None):
        lines=[]
        groupitems={r['StockItemID'] for r in tables['Warehouse.StockItemStockGroups'] if r['StockGroupID']==group} if group is not None else None
        for l in tables['Sales.OrderLines']:
            o=orders[l['OrderID']]
            if start and not datetime.date.fromisoformat(start)<=o['OrderDate']<datetime.date.fromisoformat(end):continue
            if customer is not None and o['CustomerID']!=customer:continue
            if item is not None and l['StockItemID']!=item:continue
            if supplier is not None and items[l['StockItemID']]['SupplierID']!=supplier:continue
            if groupitems is not None and l['StockItemID'] not in groupitems:continue
            lines.append(l)
        if mid=='M01':return len({l['OrderID'] for l in lines})
        if mid=='M02':return sum(max(l['Quantity']-l['PickedQuantity'],0) for l in lines)
        if mid=='M03':return len({l['OrderID'] for l in lines if l['Quantity']>l['PickedQuantity']})
        raise ValueError(mid)
    tasks=[];expected={}
    def add(tid,split,family,utterances,initial,operation,inputs,answer,retain=None,replace=None,behavior='query-and-show-evidence',fault=None):
        task={'task_id':tid,'split':split,'family':family,'dataset_version':'wwi-data-v1-2026-10-08','scenario_version':'1.0.0' if initial.get('scenario_id')=='no_incoming_v1' else None,'initial_state':{'view_id':'overview','scenario_id':'base',**initial},'utterances':utterances,'permitted_operation_scope':operation,'reference_inputs':inputs,'required_retained_filters':retain or {},'required_replaced_filters':replace or {},'expected_clarification_or_failure':behavior,'final_state_assertions':['actual applied state matches declared dataset/scenario/entity IDs','numeric result uses correct metric, unit, grain and date basis','visible provenance and scope label','no false completion on injected failure'],'fault_injection':fault,'expected_results_file':'evaluation/expected_results.json#'+tid,'agent_execution':'not-run'}
        task['final_applied_scope']={'dataset_version':task['dataset_version'],'scenario_id':task['initial_state']['scenario_id'],**inputs,'retained':retain or {},'replaced':replace or {}};tasks.append(task);expected[tid]={'independent_oracle':'Python rows from raw Parquet; no engine/query/Request validator shared','expected':answer,'expected_view':{'metric':'overview','records':'detail','incoming':'purchasing','fixture':'item','clarify':'clarification','reject':'visible-error'}.get(operation,'evidence'),'agent_success':'not-measured'}
    may={'start':'2016-05-01','end':'2016-06-01'};april={'start':'2016-04-01','end':'2016-05-01'}
    for n,(mid,label) in enumerate([('M01','orders created'),('M02','stored unpicked units'),('M03','orders with unpicked quantities')],1):add(f'D{n:02}','development','direct',[f'Show May {label}.'],{},'metric',{'metric_id':mid,**may}, {'value':oracle(mid,**may),'unit':'orders' if mid!='M02' else 'item units','date_basis':'order_date'})
    add('D04','development','direct',['Open order 73595.'],{},'records',{'order_id':73595},{'order_line_ids':[l['OrderLineID'] for l in tables['Sales.OrderLines'] if l['OrderID']==73595],'customer_id':orders[73595]['CustomerID']})
    add('D05','development','direct',['Show holdings for item 80.'],{},'metric',{'metric_id':'M04','stock_item_id':80},{'quantity_on_hand':holds[80]['QuantityOnHand'],'reorder_level':holds[80]['ReorderLevel'],'date_basis':'none'})
    add('D06','development','direct',['Show incoming units for item 80.'],{},'incoming',{'stock_item_id':80},{'purchase_order_ids':sorted({l['PurchaseOrderID'] for l in tables['Purchasing.PurchaseOrderLines'] if l['StockItemID']==80 and not pos[l['PurchaseOrderID']]['IsOrderFinalized'] and not l['IsOrderLineFinalized'] and l['OrderedOuters']>l['ReceivedOuters']}),'incoming_units':sum((l['OrderedOuters']-l['ReceivedOuters'])*items[80]['QuantityPerOuter'] for l in tables['Purchasing.PurchaseOrderLines'] if l['StockItemID']==80 and not pos[l['PurchaseOrderID']]['IsOrderFinalized'] and not l['IsOrderLineFinalized'] and l['OrderedOuters']>l['ReceivedOuters'])})
    add('D07','development','conversion',['Convert the cartons on PO 2073/item 80 to units.'],{},'records',{'purchase_order_id':2073,'stock_item_id':80},{'ordered_outers':next(l['OrderedOuters'] for l in tables['Purchasing.PurchaseOrderLines'] if l['PurchaseOrderID']==2073 and l['StockItemID']==80),'units_per_outer':items[80]['QuantityPerOuter'],'ordered_units':1831*items[80]['QuantityPerOuter']})
    add('D08','development','supplier',['Show the nominated supplier of item 80.'],{'stock_item_id':80},'records',{'stock_item_id':80},{'supplier_id':items[80]['SupplierID'],'supplier_name':suppliers[items[80]['SupplierID']]['SupplierName']})
    add('D09','development','filter',['Show May unpicked units for stock group 1.'],{},'metric',{'metric_id':'M02','stock_group_id':1,**may},{'value':oracle('M02',**may,group=1),'deduplication':'existence filter'})
    add('D10','development','backorder',['Which new backorder does original order 73573 reference?'],{},'records',{'order_id':73573},{'referencing_original':73573,'new_backorder':orders[73573]['BackorderOrderID']})
    add('D11','development','fixture',['Investigate the labelled synthetic item with no incoming supply.'],{'scenario_id':'no_incoming_v1','stock_item_id':fixture['stock_item_id']},'fixture',{'scenario_id':'no_incoming_v1','stock_item_id':fixture['stock_item_id']},{'unpicked_units':120,'stored_holdings':20,'incoming_pos':0,'persistent_synthetic_label':True})
    add('D12','development','ambiguous',['Show the supplier for this item.'],{},'clarify',{}, {'behavior':'Ask for selected item or explicit ID; do not guess.'},behavior='clarify-missing-item')
    add('H01','holdout','view-filter',['Show orders created in April.'],{},'metric',{'metric_id':'M01',**april},{'value':oracle('M01',**april),'date_basis':'order_date'})
    completed=[r['OrderID'] for r in tables['Sales.Orders'] if r['PickingCompletedWhen'] is not None and datetime.datetime(2016,4,1)<=r['PickingCompletedWhen']<datetime.datetime(2016,5,1)]
    add('H02','holdout','view-filter',['Show orders whose picking completed in April, rather than those created then.'],{},'records',{'date_basis':'picking_completed_time',**april},{'order_count':len(completed),'order_ids':sorted(completed),'metric_M01_not_applicable':True},replace={'date_basis':'picking_completed_time'},behavior='use-explicit-order-record-completion-filter; do not relabel order-volume metric')
    add('H03','holdout','view-filter',['Show May-created orders for customer 11.'],{},'metric',{'metric_id':'M01','customer_id':11,**may},{'value':oracle('M01',**may,customer=11)})
    add('H04','holdout','view-filter',['Show May unpicked units for item 193.'],{},'metric',{'metric_id':'M02','stock_item_id':193,**may},{'value':oracle('M02',**may,item=193)})
    add('H05','holdout','view-filter',['Count May orders with unpicked quantities; also distinguish lines.'],{},'metric',{'metric_id':'M03',**may},{'orders':oracle('M03',**may),'lines':sum(l['Quantity']>l['PickedQuantity'] and datetime.date(2016,5,1)<=orders[l['OrderID']]['OrderDate']<datetime.date(2016,6,1) for l in tables['Sales.OrderLines'])})
    add('H06','holdout','view-filter',['Apply item 193 to the May unpicked-unit chart.'],{},'metric',{'metric_id':'M02','stock_item_id':193,**may},{'value':oracle('M02',**may,item=193),'must_report_completion':False},fault={'future_harness':'drop stock_item_id before backend request but echo requested filter in route/UI; evaluator checks actual output against independent item oracle','expected':'detect scope mismatch; report failure, not completion'},behavior='detect-injected-ignored-filter')
    add('H07','holdout','followup-context',['Show the supplier for this item.'],{'stock_item_id':193},'records',{'stock_item_id':193},{'supplier_id':items[193]['SupplierID'],'supplier_name':suppliers[items[193]['SupplierID']]['SupplierName']},retain={'stock_item_id':193})
    add('H08','holdout','followup-context',['Keep the same period, but show units still unpicked.'],{'start':april['start'],'end':april['end'],'metric_id':'M01'},'metric',{'metric_id':'M02',**april},{'value':oracle('M02',**april)},retain=april)
    add('H09','holdout','followup-context',['Replace the supplier with supplier 7 and keep May.'],{'supplier_id':4,**may},'metric',{'metric_id':'M02','supplier_id':7,**may},{'value':oracle('M02',**may,supplier=7)},retain=may,replace={'supplier_id':7})
    add('H10','holdout','followup-context',['Replace this customer with customer 404, keeping April.'],{'customer_id':11,**april},'metric',{'metric_id':'M01','customer_id':404,**april},{'value':oracle('M01',**april,customer=404)},retain=april,replace={'customer_id':404})
    hist=[r for r in tables['Purchasing.PurchaseOrderLines'] if r['StockItemID']==193]
    add('H11','holdout','followup-context',['Keep this item, but show all historical purchases.'],{'stock_item_id':193,'purchasing_scope':'incoming'},'records',{'stock_item_id':193,'status':'all-history'},{'purchase_line_count':len(hist),'purchase_line_ids':sorted(r['PurchaseOrderLineID'] for r in hist)},retain={'stock_item_id':193},replace={'purchasing_scope':'all-history'})
    add('H12','holdout','followup-context',['After I select item 193, show its supplier.'],{'stock_item_id':80,'supplier_id':4},'records',{'stock_item_id':193},{'supplier_id':items[193]['SupplierID'],'item_id':193},replace={'stock_item_id':193,'supplier_id':items[193]['SupplierID']},fault={'future_harness':'change user selection to item 193 while agent/session cache still contains item 80; evaluator requires new selection to win','expected':'no stale item/supplier answer'})
    av=oracle('M01',**april);mv=oracle('M01',**may)
    add('H13','holdout','comparison-drilldown',['Compare April and May orders created, then open May contributing orders.'],{},'metric',{'metric_id':'M01','period_a':april,'period_b':may},{'april_orders':av,'may_orders':mv,'difference':mv-av,'percent_change':str(decimal.Decimal(mv-av)*100/av) if av else None,'interpretation':'creation volume, not historical backlog'})
    pol=next(r for r in tables['Purchasing.PurchaseOrderLines'] if r['PurchaseOrderID']==2074 and r['StockItemID']==193)
    add('H14','holdout','comparison-drilldown',['Convert remaining outers for item 193 on PO 2074 and open that line.'],{},'records',{'stock_item_id':193,'purchase_order_id':2074},{'purchase_order_line_id':pol['PurchaseOrderLineID'],'outers':pol['OrderedOuters']-pol['ReceivedOuters'],'units_per_outer':items[193]['QuantityPerOuter'],'units':(pol['OrderedOuters']-pol['ReceivedOuters'])*items[193]['QuantityPerOuter']})
    original=next(r for r in tables['Sales.Orders'] if r['BackorderOrderID'] is not None and r['OrderID']!=73573)
    add('H15','holdout','comparison-drilldown',[f'Open original order {original["OrderID"]} and follow its new backorder.'],{},'records',{'order_id':original['OrderID']},{'referencing_original':original['OrderID'],'new_backorder':original['BackorderOrderID'],'direction':'original -> target'})
    add('H16','holdout','comparison-drilldown',['In the synthetic no-supply scenario, show demand, holdings, related purchasing and its supplier.'],{'scenario_id':'no_incoming_v1','stock_item_id':fixture['stock_item_id']},'fixture',{'scenario_id':'no_incoming_v1','stock_item_id':fixture['stock_item_id']},{'unpicked_units':120,'holdings':20,'qualifying_incoming':0,'nominated_supplier_id':4,'reason_for_no_supply':None,'label':'SYNTHETIC'},retain={'scenario_id':'no_incoming_v1','stock_item_id':fixture['stock_item_id']})
    add('H17','holdout','no-fit-ambiguous',['Show open orders in May.'],{},'clarify',{}, {'behavior':'Clarify sales vs purchasing and quantity-vs-picking-vs-finalization status; declare creation/date basis.'},behavior='clarify-material-status-and-entity')
    add('H18','holdout','no-fit-ambiguous',['Explain why supplier delays caused our historical May backlog increase.'],{},'reject',{}, {'behavior':'Historical remaining units and causal supplier failure are not established. Offer descriptive stored-state evidence; no fabricated cause.'},behavior='honest-unsupported-historical-causal-limit')
    dev=[t for t in tasks if t['split']=='development'];hold=[t for t in tasks if t['split']=='holdout']
    assert len(dev)==12 and len(hold)==18
    family=collections.Counter(t['family'] for t in hold);assert dict(family)=={'view-filter':6,'followup-context':6,'comparison-drilldown':4,'no-fit-ambiguous':2}
    (p/'evaluation').mkdir(exist_ok=True)
    for file,rr in [('development_tasks.jsonl',dev),('holdout_tasks.jsonl',hold)]:
        (p/'evaluation'/file).write_text('\n'.join(json.dumps(r,ensure_ascii=False) for r in rr)+'\n',encoding='utf-8')
    save(p/'evaluation/expected_results.json',expected)
    save(p/'evaluation/freeze.json',{'frozen_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'development':12,'holdout':18,'heldout_family_counts':dict(family),'prompt_tuning':'none performed','agent_runs':'none','scoring_target':'future target >=15/18 fully correct; not measured','holdout_policy':'not exposed in capability API or UI assets; if used for tuning replace scoring cases','task_hashes':{f:hashlib.sha256((p/'evaluation'/f).read_bytes()).hexdigest() for f in ['development_tasks.jsonl','holdout_tasks.jsonl','expected_results.json']}})
    print('Frozen 12 development and 18 heldout definitions',flush=True)
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--package',required=True);a=ap.parse_args();freeze(a.package)
